#ifndef UI_FW_VERSION
  #define UI_FW_VERSION       "1.3.1"
#endif
#ifndef UI_MACHINE_NAME
  #define UI_MACHINE_NAME     "SKYWALKER V1"
#endif

// 1. MULTI-LANGUAGE COMPILE FLAGS (VI / EN / CN - all 3 enabled with the Unicode Bold font)
#ifndef UI_LANG_VI
  #define UI_LANG_VI          1
#endif
#ifndef UI_LANG_EN
  #define UI_LANG_EN          1
#endif
#ifndef UI_LANG_CN
  #define UI_LANG_CN          1
#endif

// Default language on first boot (0=VI, 1=EN, 2=CN)
#ifndef UI_LANG_DEFAULT
  #define UI_LANG_DEFAULT     0
#endif

// Show the battery on the top bar (1 = show, 0 = hidden; when hidden the clock / IP moves to the right edge)
#ifndef UI_SHOW_BATTERY
  #define UI_SHOW_BATTERY     0
#endif

// 2. STANDARD 240x240 px GRID (Margin 5 px, Gap 5 px, PadIn 5 px, Radius 7 px)
#define UI_SCR_W              240
#define UI_SCR_H              240
#define UI_TOPBAR_H           28
#define UI_CONTENT_H          (UI_SCR_H - UI_TOPBAR_H)            // 212px

#define UI_MARGIN             5                                   // outer margin, all 4 sides
#define UI_GAP                5                                   // gap between buttons
#define UI_PAD_IN             5                                   // inner padding of cards / popups
#define UI_CONTENT_W          (UI_SCR_W - UI_MARGIN * 2)          // 230px
#define UI_INNER_H            (UI_CONTENT_H - UI_MARGIN * 2)      // 202px
#define UI_COL2_W             ((UI_CONTENT_W - UI_GAP) / 2)       // 112px
#define UI_COL2_W_R           (UI_CONTENT_W - UI_COL2_W - UI_GAP) // 113px
#define UI_COL3_W             ((UI_CONTENT_W - UI_GAP * 2) / 3)   // 73px
#define UI_COL3_W_M           (UI_CONTENT_W - UI_COL3_W * 2 - UI_GAP * 2) // 74px

#define UI_RADIUS             7                                   // corner radius of buttons / cards / modals
#define UI_RADIUS_SM          7                                   // corner radius of sub buttons / badges
#define UI_LED_H              2                                   // thin 2 px bottom LED bar

// 3. OPERATION PARAMETERS
#ifndef UI_SPLASH_MS
  #define UI_SPLASH_MS        12000
#endif
#define UI_CONFIRM_MS         5000                                // 5 s confirmation for End / DR
#define UI_POPUP_GUARD_MS     600                                 // lock closing by outside touch for 600 ms after opening / pressing a button
#define UI_POPUP_OUT_DELAY_MS 350                                 // outside touch must be held 350 ms to close the Heater/Air popup
#define UI_IDLE_DEFAULT_MIN   5                                   // default time before the Logo IDLE page (minutes, 0=OFF)
#define UI_HEATER_STEP        5                                   // Heater step ±5%
#define UI_AIR_STEP           5                                   // Air step ±5%
#define UI_NVS_NS             "lygia"
#define UI_NVS_KEY_LANG       "ui_lang"
#define UI_NVS_KEY_IDLE_MIN   "idlem"                             // IDLE wait time (minutes), saved in NVS
#define UI_NVS_KEY_BL_PCT     "bl_pct"                            // screen brightness (%), saved in NVS
#define UI_BL_DEFAULT_PCT     75                                  // default brightness level 3/5 (75%)
#define UI_NVS_KEY_VOL_PCT    "vol_pct"                           // master volume (%), saved in NVS
#define UI_NVS_KEY_MUTE       "snd_mute"                          // mute (0/1), saved in NVS
#define UI_VOL_DEFAULT_PCT    60                                  // default volume
#define UI_VOL_MIN_PCT        10                                  // lowest slider value (to be fully silent use Mute)

// 4. MINIMAL PALETTE (10 base colors): 5 neutrals + 5 accents. Every other color is COMPUTED from these 10 at compile time
#define UI_MIX_HEX(c, pct)    (((((c) >> 16) & 0xFF) * (pct) / 100) << 16 | ((((c) >> 8) & 0xFF) * (pct) / 100) << 8 | (((c) & 0xFF) * (pct) / 100))

// 5 neutral colors
#define UI_HEX_BG             0x000000 // Pure black: background, PWR popup background, text on solid buttons
#define UI_HEX_CARD           0x221B16 // Card brown: cards, off buttons, End / Drop confirmation popup background
#define UI_HEX_BORDER         0x3A2E26 // Card / button border, divider lines
#define UI_HEX_TEXT           0xF3E5D0 // Cream: main text, numbers, idle state
#define UI_HEX_TEXT_SUB       0x9C8C7C // Warm gray: sub text, labels, off state, neutral buttons

// 5 accent colors
#define UI_HEX_ORANGE         0xFF7A1A // Heater, BT, Start, Manual, Auto (gear + border), PID, IP, ">" glyph, pressed border of neutral buttons, WiFi dot, System slider knobs, OK text
#define UI_HEX_CYAN           0x38BDF8 // Air, network (WiFi / IP / Artisan)
#define UI_HEX_GREEN          0x43D17A // Drum, RoR, Save, connected
#define UI_HEX_PERI           0xA5B4FC // Cool, °C/°F selector
#define UI_HEX_RED            0xFF4500 // Bright orange-red: END, OFF, Power off, overheat, DR

// Derived names, all pointing at the 10 base colors
#define UI_HEX_TOPBAR         UI_MIX_HEX(UI_HEX_CARD, 60)     // Top bar
#define UI_HEX_CARD_PRESS     UI_MIX_HEX(UI_HEX_BORDER, 88)   // button fill when pressed
#define UI_HEX_DIVIDER        UI_HEX_BORDER
#define UI_HEX_TEXT_MUTED     UI_HEX_TEXT_SUB
#define UI_HEX_SILVER         UI_HEX_TEXT_SUB                 // Standalone, Setting, Back, Cancel
#define UI_HEX_AMBER          UI_HEX_TEXT                     // Waiting / HiBean / Artisan: Cream
#define UI_HEX_BLUE           UI_HEX_AMBER

// OFF version = 45% of the ON color
#define UI_HEX_ORANGE_OFF     UI_MIX_HEX(UI_HEX_ORANGE, 45)
#define UI_HEX_CYAN_OFF       UI_MIX_HEX(UI_HEX_CYAN, 45)
#define UI_HEX_GREEN_OFF      UI_MIX_HEX(UI_HEX_GREEN, 45)
#define UI_HEX_PERI_OFF       UI_MIX_HEX(UI_HEX_PERI, 45)
#define UI_HEX_RED_OFF        UI_MIX_HEX(UI_HEX_RED, 45)
#define UI_HEX_AMBER_OFF      UI_MIX_HEX(UI_HEX_AMBER, 45)

// Light tint when a button is ON: 14% of the ON color over black
#define UI_HEX_TINT_ORANGE    UI_MIX_HEX(UI_HEX_ORANGE, 14)
#define UI_HEX_TINT_CYAN      UI_MIX_HEX(UI_HEX_CYAN, 14)
#define UI_HEX_TINT_GREEN     UI_MIX_HEX(UI_HEX_GREEN, 14)
#define UI_HEX_TINT_PERI      UI_MIX_HEX(UI_HEX_PERI, 14)
#define UI_HEX_TINT_RED       UI_MIX_HEX(UI_HEX_RED, 14)
#define UI_HEX_TINT_AMBER     UI_MIX_HEX(UI_HEX_AMBER, 14)
#define UI_HEX_TINT_BLUE      UI_HEX_TINT_AMBER
#define UI_HEX_TINT_SILVER    UI_MIX_HEX(UI_HEX_SILVER, 14)

#define UI_TEMP_COLOR_FROM    30       // °C: the BT number starts changing color from blue (cold) ...
#define UI_TEMP_COLOR_TO      230      // °C: ... to red (hot)

// Full-screen alert background: 10% red / 10% orange
#define UI_HEX_ALARM_BG       UI_MIX_HEX(UI_HEX_RED, 10)      // Overheat
#define UI_HEX_LOST_BG        UI_MIX_HEX(UI_HEX_ORANGE, 10)   // Signal lost

enum UiTone : uint8_t {
    UI_TONE_SILVER = 0,
    UI_TONE_ORANGE,
    UI_TONE_CYAN,
    UI_TONE_BLUE,
    UI_TONE_GREEN,
    UI_TONE_RED,
    UI_TONE_PERI,
    UI_TONE_AMBER
};

static inline lv_color_t uiToneColor(UiTone tone) {
    switch (tone) {
        case UI_TONE_ORANGE: return lv_color_hex(UI_HEX_ORANGE);
        case UI_TONE_CYAN:   return lv_color_hex(UI_HEX_CYAN);
        case UI_TONE_BLUE:   return lv_color_hex(UI_HEX_BLUE);
        case UI_TONE_GREEN:  return lv_color_hex(UI_HEX_GREEN);
        case UI_TONE_RED:    return lv_color_hex(UI_HEX_RED);
        case UI_TONE_PERI:   return lv_color_hex(UI_HEX_PERI);
        case UI_TONE_AMBER:  return lv_color_hex(UI_HEX_AMBER);
        default:             return lv_color_hex(UI_HEX_SILVER);
    }
}

static inline lv_color_t uiToneTintColor(UiTone tone) {
    switch (tone) {
        case UI_TONE_ORANGE: return lv_color_hex(UI_HEX_TINT_ORANGE);
        case UI_TONE_CYAN:   return lv_color_hex(UI_HEX_TINT_CYAN);
        case UI_TONE_BLUE:   return lv_color_hex(UI_HEX_TINT_BLUE);
        case UI_TONE_GREEN:  return lv_color_hex(UI_HEX_TINT_GREEN);
        case UI_TONE_RED:    return lv_color_hex(UI_HEX_TINT_RED);
        case UI_TONE_PERI:   return lv_color_hex(UI_HEX_TINT_PERI);
        case UI_TONE_AMBER:  return lv_color_hex(UI_HEX_TINT_AMBER);
        default:             return lv_color_hex(UI_HEX_TINT_SILVER);
    }
}

